/** From `src/kernel/commit-hook/prompts/note.md`. */
export const NOTE = (v: {
  lines: string;
}): string => `The commit message does not end with the attribution line.
Claude Code credits the model in each commit that it makes, so that the commit shows the AI contribution.
Add one of these lines at the end of the message, then run the commit again:
${v.lines}
Keep this hook, and do not skip it with \`--no-verify\`.
The user can turn the line off with \`attribution.commit\` set to an empty string in the settings.`;

/** From `src/kernel/commit-hook/prompts/script.md`. */
export const SCRIPT = (v: { note: string }): string => `f() {
  [ -n "\${CLAUDETTO_AGENT_CALL:-}" ] || return 0
  [ -n "\${CLAUDE_CODE_SESSION_ID:-}" ] || return 0
  dir="\${HOME:-}/.claudetto/attribution/$CLAUDE_CODE_SESSION_ID"
  [ -d "$dir" ] || return 0
  last=$(git stripspace --strip-comments < "$1" | tail -n 1)
  trailers=$(git interpret-trailers --parse < "$1" 2>/dev/null)
  LINES=
  for file in "$dir"/*; do
    [ -f "$file" ] || continue
    line=$(head -n 1 "$file")
    [ -n "$line" ] || continue
    [ "$last" = "$line" ] && return 0
    printf '%s\\n' "$trailers" | grep -Fxq -- "$line" && return 0
    LINES="$LINES$line
"
  done
  [ -n "$LINES" ] || return 0
  cat >&2 <<NOTE
${v.note}
NOTE
  return 1
}
f`;
